#!/usr/bin/env python3
"""Train consistent heavy-atom/FPA diffusion from scratch."""
from __future__ import annotations
import argparse,json,math,random,time
from pathlib import Path
import numpy as np,torch,torch.nn.functional as F,yaml
from torch.utils.data import DataLoader
from polyring_diffusion.chem import element_record
from polyring_diffusion.fpa_data_v2 import FPAEntityDatasetV2,collate_fpa_v2
from polyring_diffusion.fpa_diffusion_v2 import extract,masked_center
from polyring_diffusion.so3_diffusion import MolecularDiffusion
from polyring_diffusion.fpa_model_v2 import FPAEntityDenoiserV2

def bce(logits,target):
 flat=target.reshape(-1);counts=torch.bincount(flat,minlength=logits.shape[-1]).float().clamp_min(1);w=(counts.sum()/counts).clamp_max(20);w=w/w.mean();return F.cross_entropy(logits.reshape(-1,logits.shape[-1]),flat,weight=w)
def masked(x,m):x=x[m];return x.mean() if x.numel() else m.new_zeros((),dtype=torch.float32)
def q_free(clean,t,schedule,mask):
 eps=torch.randn_like(clean)*mask.unsqueeze(-1);a=extract(schedule.abar,t,clean.ndim);return (a.sqrt()*clean+(1-a).sqrt()*eps)*mask.unsqueeze(-1),eps
def forward_batch(raw,model,diff,device,training=True):
 b={k:v.to(device,non_blocking=True) for k,v in raw.items()};am,cm=b['atom_mask'],b['cell_mask'];ap=am[:,:,None]&am[:,None];cp=cm[:,:,None]&cm[:,None];cross=cm[:,:,None]&am[:,None];t=torch.randint(diff.timesteps,(len(am),),device=device)
 apos,ae=diff.q_coordinates(b['atom_positions'],t,am);cpos,ce=q_free(b['cell_centers'],t,diff,cm);radius,re=q_free(b['cell_radii'].clamp_min(.1).log().unsqueeze(-1),t,diff,cm);frame,omega=diff.q_frames(b['cell_frames'],t,cm)
 at=diff.q_tokens(torch.where(am,b['atom_types'],model.atom_pad_token),t,model.atom_mask_token,am);charge=diff.q_tokens(model.charge_index(b['atom_charges']),t,model.charge_mask_token,am);ct=diff.q_tokens(torch.where(cm,b['cell_types'],model.cell_pad_token),t,model.cell_mask_token,cm);size=diff.q_tokens(b['cell_sizes'],t,model.size_mask_token,cm);bond=diff.q_symmetric_tokens(b['atom_bond_types'],t,5,ap);fusion=diff.q_symmetric_tokens(b['fusion_types'],t,2,cp);member=diff.q_tokens(b['cell_membership'].long(),t,2,cross);drop=(torch.rand(len(am),device=device)<model.condition_dropout) if training else None
 p=model(at,charge,apos,bond,am,ct,size,cpos,frame,radius.squeeze(-1),fusion,member,cm,t,b['property'],drop);return b,p,(ae,ce,re.squeeze(-1),omega),t,(apos,cpos,radius.squeeze(-1),frame)
def terms(pack,model,diff,cov,max_valence):
 b,p,target,t,noisy=pack;ae,ce,re,omega=target;apos,cpos,radius,frame=noisy;am,cm=b['atom_mask'],b['cell_mask'];au=am[:,:,None]&am[:,None]&torch.triu(torch.ones(am.shape[1],am.shape[1],dtype=torch.bool,device=am.device),1)[None];cu=cm[:,:,None]&cm[:,None]&torch.triu(torch.ones(cm.shape[1],cm.shape[1],dtype=torch.bool,device=cm.device),1)[None];cross=cm[:,:,None]&am[:,None]
 x0=masked_center(diff.predict_x0(apos,p['atom_eps'],t),am);c0=diff.predict_x0(cpos,p['cell_eps'],t);r0=diff.predict_x0(radius,p['radius_eps'],t).exp().clamp(.1,10.);mprob=p['membership_logits'].softmax(-1)[...,1]*cross;den=mprob.sum(-1,keepdim=True).clamp_min(1);derived=(mprob[...,None]*x0[:,None]).sum(2)/den
 frame0=diff.denoise_frames(frame,p['rotation_score'],t,cm);rel=x0[:,None]-c0[:,:,None];normal=frame0[...,2];height=(rel*normal[:,:,None]).sum(-1);radial=(rel-height[...,None]*normal[:,:,None]).norm(dim=-1);geom=((derived-c0).square().sum(-1)+(mprob*height.square()).sum(-1)/den.squeeze(-1)+(mprob*(radial-r0[:,:,None]).square()).sum(-1)/den.squeeze(-1))
 bondprob=p['bond_logits'].softmax(-1);orders=bondprob.new_tensor([0.,1.,2.,3.,1.5]);expected=(bondprob*orders).sum(-1);chem_pair=am[:,:,None]&am[:,None,:]&~torch.eye(am.shape[1],dtype=torch.bool,device=am.device)[None];expected=expected*chem_pair;valence=expected.sum(-1);allowed=max_valence[b['atom_types']];val_loss=masked(F.relu(valence-allowed).square(),am);dist=(x0[:,:,None]-x0[:,None]).norm(dim=-1);pair_cov=cov[b['atom_types']][:,:,None]+cov[b['atom_types']][:,None];factors=bondprob.new_tensor([1.,1.,.90,.82,.95]);target_len=(bondprob*factors).sum(-1)*pair_cov;bond_len=masked((dist-target_len).square(),au&b['atom_bond_types'].gt(0));degree=((1-bondprob[...,0])*chem_pair).sum(-1);connected=masked(F.relu(1-degree),am)
 overlap=torch.einsum('bca,bda->bcd',mprob,mprob);fusion_soft=p['fusion_logits'].softmax(-1)[...,1];fusion_cons=masked((fusion_soft-torch.sigmoid(4*(overlap-1.5))).square(),cu);cardinality=masked((mprob.sum(-1)-b['cell_sizes'].float()).square(),cm);target_overlap=torch.einsum('bca,bda->bcd',b['cell_membership'].float(),b['cell_membership'].float());shared_atoms=masked(torch.where(b['fusion_types'].bool(),(overlap-2).square(),F.relu(overlap-1).square()),cu);co_member=torch.einsum('bca,bcj->baj',b['cell_membership'].float(),b['cell_membership'].float()).gt(0);aromatic_mask=au&co_member&b['atom_bond_types'].eq(4);aromatic=masked(-p['bond_logits'].log_softmax(-1)[...,4],aromatic_mask)
 return {'atom_eps':masked((p['atom_eps']-ae).square().sum(-1),am),'cell_eps':masked((p['cell_eps']-ce).square().sum(-1),cm),'radius_eps':masked((p['radius_eps']-re).square(),cm),'rotation':masked(((p['rotation_score']-omega)*extract(diff.rot_sigma,t,omega.ndim)).square().sum(-1),cm),'atom_type':bce(p['atom_type_logits'][am],b['atom_types'][am]),'charge':bce(p['charge_logits'][am],model.charge_index(b['atom_charges'])[am]),'bond':bce(p['bond_logits'][au],b['atom_bond_types'][au]) if au.any() else val_loss*0,'cell_type':bce(p['cell_type_logits'][cm],b['cell_types'][cm]) if cm.any() else val_loss*0,'cell_size':bce(p['cell_size_logits'][cm],b['cell_sizes'][cm]) if cm.any() else val_loss*0,'fusion':bce(p['fusion_logits'][cu],b['fusion_types'][cu]) if cu.any() else val_loss*0,'membership':bce(p['membership_logits'][cross],b['cell_membership'][cross].long()) if cross.any() else val_loss*0,'atom_count':bce(p['atom_count_logits'],am.sum(1)),'cell_count':bce(p['cell_count_logits'],cm.sum(1)),'cell_geometry':masked(geom,cm),'fusion_consistency':fusion_cons,'cell_cardinality':cardinality,'shared_atoms':shared_atoms,'aromatic':aromatic,'valence':val_loss,'bond_length':bond_len,'connectivity':connected}
def main():
 a=argparse.ArgumentParser();a.add_argument('--config',default='scripts/qcdge_a10_fpa_v2.yaml');a.add_argument('--resume');args=a.parse_args();cfg=yaml.safe_load(Path(args.config).read_text());random.seed(cfg['seed']);np.random.seed(cfg['seed']);torch.manual_seed(cfg['seed']);dev=torch.device(cfg.get('device','cuda'))
 train=FPAEntityDatasetV2(cfg['data']['root'],'train');val=FPAEntityDatasetV2(cfg['data']['root'],'val',train.property_mean,train.property_std,condition_stats=train.condition_stats,frame_augmentation=False);mc=dict(cfg['model']);mc.update(num_atom_types=train.num_atom_types,num_cell_types=len(train.template_hash_to_id),atom_radii=[element_record(x).vdw_radius/3 for x in train.atom_map],max_cell_ports=train.max_cell_ports,max_atoms=train.max_heavy_atoms,max_cells=train.max_fpa_cells);model=FPAEntityDenoiserV2(**mc).to(dev);diff=MolecularDiffusion(**cfg['diffusion']).to(dev);cov=torch.tensor([element_record(x).covalent_radius for x in train.atom_map],device=dev);valences=torch.tensor([3,4,3,2,1,4,5,6,1,1,1],device=dev,dtype=torch.float32)
 opt=torch.optim.AdamW(model.parameters(),lr=float(cfg['training']['learning_rate']),weight_decay=float(cfg['training']['weight_decay']));sch=torch.optim.lr_scheduler.CosineAnnealingLR(opt,T_max=cfg['training']['epochs']);start=step=0
 if args.resume:s=torch.load(args.resume,map_location=dev,weights_only=False);model.load_state_dict(s['model']);opt.load_state_dict(s['optimizer']);sch.load_state_dict(s['scheduler']);start=s['epoch']+1;step=s['step']
 load=lambda ds,shuffle:DataLoader(ds,batch_size=cfg['training']['batch_size'],shuffle=shuffle,num_workers=cfg['training'].get('num_workers',0),collate_fn=collate_fpa_v2,pin_memory=True);tl,vl=load(train,True),load(val,False);w=cfg['training']['loss_weights'];run=Path(cfg['training']['output_dir']);run.mkdir(parents=True,exist_ok=True);(run/'config.resolved.yaml').write_text(yaml.safe_dump(cfg));log=(run/'metrics.jsonl').open('a',buffering=1);best=math.inf
 for epoch in range(start,cfg['training']['epochs']):
  model.train();total=nb=0;tic=time.time()
  for raw in tl:
   with torch.autocast('cuda',dtype=torch.bfloat16,enabled=dev.type=='cuda' and cfg['training'].get('bf16',True)):ts=terms(forward_batch(raw,model,diff,dev),model,diff,cov,valences);loss=sum(w.get(k,0)*v for k,v in ts.items())
   opt.zero_grad(set_to_none=True);loss.backward();torch.nn.utils.clip_grad_norm_(model.parameters(),cfg['training']['grad_clip']);opt.step();total+=float(loss.detach());nb+=1;step+=1
  model.eval();vtotal=vn=0;gain=0
  with torch.no_grad():
   for raw in vl:
    cpu_rng=torch.get_rng_state();cuda_rng=torch.cuda.get_rng_state(dev) if dev.type=='cuda' else None;pack=forward_batch(raw,model,diff,dev,False);ts=terms(pack,model,diff,cov,valences);base_total=sum(w.get(k,0)*v for k,v in ts.items());vtotal+=float(base_total);torch.set_rng_state(cpu_rng);torch.cuda.set_rng_state(cuda_rng,dev) if cuda_rng is not None else None;shifted=dict(raw);shifted['property']=raw['property'].roll(1,0);shifted_terms=terms(forward_batch(shifted,model,diff,dev,False),model,diff,cov,valences);gain+=float(sum(w.get(k,0)*v for k,v in shifted_terms.items())-base_total);vn+=1
    if vn>=cfg['training'].get('validation_batches',10):break
  sch.step();metrics={'epoch':epoch,'step':step,'train_loss':total/nb,'val_loss':vtotal/vn,'condition_shuffle_gain':gain/vn,'seconds':time.time()-tic};print(json.dumps(metrics),flush=True);log.write(json.dumps(metrics)+'\n');state={'model':model.state_dict(),'optimizer':opt.state_dict(),'scheduler':sch.state_dict(),'epoch':epoch,'step':step,'config':cfg,'atom_map':train.atom_map,'condition_stats':train.condition_stats,'manifest':train.manifest,'metrics':metrics};torch.save(state,run/'last.pt');
  if metrics['val_loss']<best:best=metrics['val_loss'];torch.save(state,run/'best.pt')
if __name__=='__main__':main()
